export default function HomePage() {
  const [boards, setBoards] = useState<Board[]>(initialBoards);
  const [creating, setCreating] = useState(false);

  function addBoard(title: string, vibe: string) {
    const newBoard: Board = {
      id: crypto.randomUUID(),
      title,
      vibe,
      x: `${10 + Math.random() * 65}%`,
      y: `${10 + Math.random() * 60}%`,
      rotation: Math.random() * 8 - 4,
      pinColor: ["#e11d48", "#2563eb", "#16a34a", "#d97706"][
        Math.floor(Math.random() * 4)
      ],
      previewImages: [
        "https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=700&q=80",
        "https://images.unsplash.com/photo-1484154218962-a197022b5858?auto=format&fit=crop&w=500&q=80",
        "https://images.unsplash.com/photo-1494526585095-c41746248156?auto=format&fit=crop&w=500&q=80",
      ],
    };

    setBoards((prev) => [...prev, newBoard]);
    setCreating(false);
  }

  return (
    <main className="min-h-screen bg-[#f5f1ea] px-6 py-8 md:px-10">
      <div className="mx-auto max-w-[1600px]">
        <div className="mb-6 flex items-start justify-between gap-4">
          <div>
            <p className="mb-3 text-sm uppercase tracking-[0.35em] text-[#7f766d]">
              Mosaic
            </p>
            <h1 className="max-w-3xl text-4xl font-semibold leading-tight text-[#231f1c] md:text-6xl">
              Your worlds, all in one place.
            </h1>
          </div>

          <button
            onClick={() => setCreating(true)}
            className="rounded-full bg-[#171412] px-6 py-4 text-sm font-medium text-white shadow transition hover:scale-[1.02]"
          >
            + Create Board
          </button>
        </div>

        <section
          className="relative min-h-[760px] overflow-hidden rounded-[2.2rem] border-[18px] border-[#825839] shadow-[0_20px_50px_rgba(0,0,0,0.12)]"
          style={{
            backgroundColor: "#c7925f",
            backgroundImage:
              "radial-gradient(rgba(120,78,45,0.28) 1px, transparent 1px)",
            backgroundSize: "10px 10px",
          }}
        >
          <div className="absolute inset-0 bg-[linear-gradient(to_bottom,rgba(255,255,255,0.05),rgba(0,0,0,0.04))]" />

          {boards.map((board) => (
            <ProjectPin key={board.id} {...board} />
          ))}
        </section>
      </div>

      {creating && (
        <CreateBoardModal
          onClose={() => setCreating(false)}
          onCreate={addBoard}
        />
      )}
    </main>
  );
}